async function removeDefaultZones(): Promise<void> {
  if (!(await exists(TRADERZONES_DIR))) {
    log(
      `${TRADERZONES_DIR} not generated yet - DayZ-Expansion-Market will create it on first ` +
        "server start, nothing to remove yet",
    );
    return;
  }

  let removed = 0;
  for (const file of DEFAULT_ZONE_FILES) {
    const path = `${TRADERZONES_DIR}/${file}`;
    if (await exists(path)) {
      await Deno.remove(path);
      removed++;
    }
  }
  if (removed > 0) {
    ok(`Removed ${removed} default DayZ-Expansion-Market trader zone(s) from ${TRADERZONES_DIR}`);
  }
}

// A single, empty-slotted ExpansionPrefabObject - matches
// DayZ-Expansion-Core's own JsonFileLoader-serialized shape
// (ExpansionPrefabObject.c) so its JsonFileLoader<ExpansionLoadout> can
// parse these files back out with no further defaults needed.
function gearItemJson(className: string): Record<string, unknown> {
  return {
    ClassName: className,
    Include: "",
    Chance: 1.0,
    Quantity: { Min: 0, Max: 0 },
    Health: [],
    InventoryAttachments: [],
    InventoryCargo: [],
    ConstructionPartsBuilt: [],
    Sets: [],
  };
}

function loadoutJson(gear: GearSlot[]): string {
  return JSON.stringify(
    {
      ClassName: "",
      Include: "",
      Chance: 1.0,
      Quantity: { Min: 0, Max: 0 },
      Health: [],
      InventoryAttachments: gear.map((g) => ({
        SlotName: g.slot,
        Items: [gearItemJson(g.className)],
      })),
      InventoryCargo: [],
      ConstructionPartsBuilt: [],
      Sets: [],
    },
    null,
    4,
  );
}

async function ensureCustomTraderGear(): Promise<void> {
  await Deno.mkdir(EXPANSION_LOADOUTS_DIR, { recursive: true });

  let changed = 0;
  for (const loadout of CUSTOM_LOADOUTS) {
    const path = `${EXPANSION_LOADOUTS_DIR}/${loadout.name}.json`;
    const body = loadoutJson(loadout.gear);
    const existing = (await exists(path)) ? await Deno.readTextFile(path) : null;
    if (existing !== body) {
      await Deno.writeTextFile(path, body);
      changed++;
    }
  }
  if (changed > 0) {
    ok(`Wrote ${changed} custom trader gear loadout(s) to ${EXPANSION_LOADOUTS_DIR}`);
  }
}

async function ensureCustomTraderIdentities(): Promise<void> {
  if (!(await exists(EXPANSION_TRADERS_DIR))) {
    log(
      `${EXPANSION_TRADERS_DIR} not generated yet - DayZ-Expansion-Market will create it on ` +
        "first server start, nothing to add yet",
    );
    return;
  }

  let changed = 0;
  for (const identity of CUSTOM_TRADER_IDENTITIES) {
    const path = `${EXPANSION_TRADERS_DIR}/${identity.fileName}.json`;
    const body = JSON.stringify(
      {
        m_Version: 13,
        DisplayName: identity.displayName,
        MinRequiredReputation: 0,
        MaxRequiredReputation: 2147483647,
        RequiredFaction: "",
        RequiredCompletedQuestID: -1,
        TraderIcon: identity.icon,
        // Real, physical currency (see GOLD_CURRENCY_CLASSNAME/
        // ensureGoldCoinCurrency() below) - DayZ-Expansion-Core ships this
        // item out of the box (core_objects_currencies.pbo, confirmed via
        // its own wiki: "gold/silver bars and nuggets we provide by default
        // with the Expansion Core mod"), so no extra mod/risk was needed.
        // Matches MarketSettings.json's own CurrencyIcon, a gold coin stack
        // graphic (coinstack2_64x64.edds).
        Currencies: [GOLD_CURRENCY_CLASSNAME],
        DisplayCurrencyValue: 1,
        DisplayCurrencyName: "Gold Coin",
        UseCategoryOrder: 0,
        Categories: identity.categories,
        Items: {},
      },
      null,
      4,
    );
    const existing = (await exists(path)) ? await Deno.readTextFile(path) : null;
    if (existing !== body) {
      await Deno.writeTextFile(path, body);
      changed++;
    }
  }
  if (changed > 0) {
    ok(`Wrote ${changed} custom trader identity file(s) to ${EXPANSION_TRADERS_DIR}`);
  }
}

function traderMapLine(npc: CustomTraderNpc, origin: [number, number, number]): string {
  const pos = origin.map((v, i) => v + npc.offset[i]).map((n) => n.toFixed(3)).join(" ");
  const orientation = npc.orientation.join(" ");
  return `${npc.entity}.${npc.traderFile}|${pos}|${orientation}|${npc.gear ?? ""}`;
}

// Shape of the zone file this CLI owns. Only m_DisplayName/Position/Radius/
// BuyPricePercent/SellPricePercent are ever written by this CLI - Stock is
// the *live*, real running per-item stock map, populated and persisted
// entirely by the game itself (ExpansionMarketTraderZone.Save()) as players
// buy/sell - confirmed live (1800+ real entries accumulate here during
// normal play). m_Version is left untouched too in case the game bumps it.
interface CustomZoneFile {
  m_Version: number;
  m_DisplayName: string;
  Position: [number, number, number];
  Radius: number;
  BuyPricePercent: number;
  SellPricePercent: number;
  Stock: Record<string, number>;
  [key: string]: unknown;
}

async function ensureCustomZone(): Promise<void> {
  if (!CUSTOM_POSITION) {
    warn(
      "Custom trader position not set yet (CUSTOM_POSITION in src/traders.ts) - skipping custom " +
        "trader zone/NPC setup. Scout a real position in-game as admin (see MODS.md's Admin tools " +
        "section: COT's free cam/`INSERT` + position readout), fill it in, then re-run.",
    );
    return;
  }

  await Deno.mkdir(TRADERZONES_DIR, { recursive: true });
  const zonePath = `${TRADERZONES_DIR}/${CUSTOM_ZONE_NAME}.json`;

  const existing: CustomZoneFile | null = (await exists(zonePath))
    ? JSON.parse(await Deno.readTextFile(zonePath))
    : null;

  // IMPORTANT: never rebuild this object from scratch once it exists - only
  // ever patch the specific fields this CLI actually owns onto the existing
  // object, preserving Stock (and anything else the game itself may have
  // added) untouched. Rebuilding unconditionally with a hardcoded `Stock: {}`
  // was a real, confirmed bug: since this runs on every server start (via
  // ensureCustomTrader()), it silently wiped every player's sold-in trader
  // stock back to empty on every single restart.
  const zone: CustomZoneFile = existing ?? {
    m_Version: 6,
    m_DisplayName: "Custom Trading Zone",
    Position: CUSTOM_POSITION,
    Radius: CUSTOM_RADIUS,
    BuyPricePercent: 100.0,
    SellPricePercent: -1.0,
    Stock: {},
  };

  let changed = !existing;
  if (zone.m_DisplayName !== "Custom Trading Zone") {
    zone.m_DisplayName = "Custom Trading Zone";
    changed = true;
  }
  if (JSON.stringify(zone.Position) !== JSON.stringify(CUSTOM_POSITION)) {
    zone.Position = CUSTOM_POSITION;
    changed = true;
  }
  if (zone.Radius !== CUSTOM_RADIUS) {
    zone.Radius = CUSTOM_RADIUS;
    changed = true;
  }
  if (zone.BuyPricePercent !== 100.0) {
    zone.BuyPricePercent = 100.0;
    changed = true;
  }
  if (zone.SellPricePercent !== -1.0) {
    zone.SellPricePercent = -1.0;
    changed = true;
  }
  if (!zone.Stock) {
    zone.Stock = {};
    changed = true;
  }

  if (changed) {
    await Deno.writeTextFile(zonePath, JSON.stringify(zone, null, 4));
    ok(`Wrote ${zonePath}`);
  }

  await Deno.mkdir(TRADERS_DIR, { recursive: true });
  const mapPath = `${TRADERS_DIR}/${CUSTOM_ZONE_NAME}.map`;
  const mapBody = CUSTOM_NPCS.map((npc) => traderMapLine(npc, CUSTOM_POSITION)).join("\n") + "\n";
  const existingMap = (await exists(mapPath)) ? await Deno.readTextFile(mapPath) : null;
  if (existingMap !== mapBody) {
    await Deno.writeTextFile(mapPath, mapBody);
    ok(`Wrote ${mapPath} (${CUSTOM_NPCS.length} trader NPCs)`);
  }
}

// DayZ-Expansion-Core's own SafeZoneSettings.json schema (confirmed live -
// see server/mpmissions/dayzOffline.chernarusplus/expansion/settings/
// SafeZoneSettings.json, self-generated with Chernarus' default city safe
// zones already in CircleZones). Only the fields this reads/writes are
// typed; everything else round-trips untouched via the index signature.
interface SafeZoneCircleZone {
  Center: [number, number, number];
  Radius: number;
}

interface SafeZoneSettings {
  CircleZones: SafeZoneCircleZone[];
  [key: string]: unknown;
}

async function ensureCustomTraderSafeZone(): Promise<void> {
  if (!CUSTOM_POSITION) return; // same guard as ensureCustomZone() above

  if (!(await exists(SAFE_ZONE_SETTINGS))) {
    log(
      `${SAFE_ZONE_SETTINGS} not generated yet - DayZ-Expansion-Core will create it on first ` +
        "server start, nothing to add yet",
    );
    return;
  }

  const settings: SafeZoneSettings = JSON.parse(await Deno.readTextFile(SAFE_ZONE_SETTINGS));
  const existing = settings.CircleZones.find(
    (z) =>
      Math.abs(z.Center[0] - CUSTOM_POSITION[0]) < 1 &&
      Math.abs(z.Center[2] - CUSTOM_POSITION[2]) < 1,
  );

  if (existing) {
    if (existing.Radius === CUSTOM_SAFE_ZONE_RADIUS) return;
    const oldRadius = existing.Radius;
    existing.Radius = CUSTOM_SAFE_ZONE_RADIUS;
    await Deno.writeTextFile(SAFE_ZONE_SETTINGS, JSON.stringify(settings, null, 4));
    ok(
      `Updated the custom trader city safe zone radius from ${oldRadius}m to ` +
        `${CUSTOM_SAFE_ZONE_RADIUS}m in ${SAFE_ZONE_SETTINGS}`,
    );
    return;
  }

  settings.CircleZones.push({ Center: CUSTOM_POSITION, Radius: CUSTOM_SAFE_ZONE_RADIUS });
  await Deno.writeTextFile(SAFE_ZONE_SETTINGS, JSON.stringify(settings, null, 4));
  ok(
    `Added a ${CUSTOM_SAFE_ZONE_RADIUS}m safe zone at the custom trader city to ` +
      SAFE_ZONE_SETTINGS,
  );
}

// DayZ-Expansion-Market's global vehicle-spawn registry (self-generated the
// first time the mission loads, with 5-6 default entries all clustered near
// the vanilla trader city). Only the fields this reads/writes are typed;
// everything else (WaterSpawnPositions, distance settings, etc.) round-trips
// untouched via the index signature.
interface MarketSpawnPosition {
  Position: [number, number, number];
  Orientation: [number, number, number];
}

interface MarketSettings {
  LandSpawnPositions: MarketSpawnPosition[];
  AirSpawnPositions: MarketSpawnPosition[];
  [key: string]: unknown;
}

function ensureVehicleSpawnPositionList(
  list: MarketSpawnPosition[],
  points: VehicleSpawnPoint[],
  customPosition: [number, number, number],
  label: string,
): number {
  let added = 0;
  for (const point of points) {
    const absolute: [number, number, number] = [
      customPosition[0] + point.offset[0],
      customPosition[1] + point.offset[1],
      customPosition[2] + point.offset[2],
    ];
    const alreadyThere = list.some(
      (p) => Math.abs(p.Position[0] - absolute[0]) < 1 && Math.abs(p.Position[2] - absolute[2]) < 1,
    );
    if (alreadyThere) continue;
    list.push({ Position: absolute, Orientation: point.orientation });
    added++;
  }
  if (added > 0) {
    ok(`Added ${added} ${label} vehicle spawn position(s) near the custom trader city`);
  }
  return added;
}

async function ensureCustomVehicleSpawnPositions(): Promise<void> {
  if (!CUSTOM_POSITION) return; // same guard as ensureCustomZone() above
  const customPosition = CUSTOM_POSITION;

  if (
    CUSTOM_LAND_VEHICLE_SPAWN_POINTS.length === 0 &&
    CUSTOM_AIR_VEHICLE_SPAWN_POINTS.length === 0
  ) {
    warn(
      "CUSTOM_LAND_VEHICLE_SPAWN_POINTS/CUSTOM_AIR_VEHICLE_SPAWN_POINTS are both empty - " +
        "vehicle purchases at the custom trader city will fail with 'no air/land spawn space' " +
        "until you scout real, clear positions near the Vehicle Dealer NPC and fill them in " +
        "(see the TODO comment above those constants in src/traders.ts)",
    );
    return;
  }

  if (!(await exists(MARKET_SETTINGS))) {
    log(
      `${MARKET_SETTINGS} not generated yet - DayZ-Expansion-Market will create it on first ` +
        "server start, nothing to add yet",
    );
    return;
  }

  const settings: MarketSettings = JSON.parse(await Deno.readTextFile(MARKET_SETTINGS));
  const addedLand = ensureVehicleSpawnPositionList(
    settings.LandSpawnPositions,
    CUSTOM_LAND_VEHICLE_SPAWN_POINTS,
    customPosition,
    "land",
  );
  const addedAir = ensureVehicleSpawnPositionList(
    settings.AirSpawnPositions,
    CUSTOM_AIR_VEHICLE_SPAWN_POINTS,
    customPosition,
    "air",
  );

  if (addedLand > 0 || addedAir > 0) {
    await Deno.writeTextFile(MARKET_SETTINGS, JSON.stringify(settings, null, 4));
  }
}

// Exchange.json (profiles/ExpansionMod/Market/) is DayZ-Expansion-Market's
// dedicated currency category (IsExchange: 1 - see market.ts's
// writeMergedCategory(), which always sets IsExchange: 0 for every *other*
// managed category, deliberately leaving this one alone) - self-generated
// with expansionbanknotehryvnia as its sole item on first server start,
// same timing as everything else under EXPANSION_MARKET_DIR/MARKET_SETTINGS
// (see tuneExpansionMarket()/ensureCustomVehicleSpawnPositions()).
interface ExchangeCategory {
  m_Version: number;
  DisplayName: string;
  Icon: string;
  Color: string;
  IsExchange: number;
  InitStockPercent: number;
  Items: {
    ClassName: string;
    MaxPriceThreshold: number;
    MinPriceThreshold: number;
    SellPricePercent: number;
    MaxStockThreshold: number;
    MinStockThreshold: number;
    QuantityPercent: number;
    SpawnAttachments: unknown[];
    Variants: unknown[];
  }[];
}

const EXCHANGE_FILE = `${EXPANSION_MARKET_DIR}/Exchange.json`;

// Makes GOLD_CURRENCY_CLASSNAME the one and only currency, both at the
// trader (Exchange.json - what the market system will mint/accept as
// change) and at the ATM (MarketSettings.json's own separate Currencies
// list - confirmed via DayZ-Expansion-Scripts' own wiki, "[Server Hosting]
// Setting up Custom Market Currencies": trader currency and ATM currency are
// two independently-configured lists, not derived from each other).
async function ensureGoldCoinCurrency(): Promise<void> {
  if (await exists(EXCHANGE_FILE)) {
    const data: ExchangeCategory = JSON.parse(await Deno.readTextFile(EXCHANGE_FILE));
    const alreadyGold = data.Items.length === 1 &&
      data.Items[0].ClassName === GOLD_CURRENCY_CLASSNAME;
    if (!alreadyGold) {
      data.Items = [
        {
          ClassName: GOLD_CURRENCY_CLASSNAME,
          MaxPriceThreshold: 1,
          MinPriceThreshold: 1,
          SellPricePercent: -1,
          MaxStockThreshold: 1,
          MinStockThreshold: 1,
          QuantityPercent: -1,
          SpawnAttachments: [],
          Variants: [],
        },
      ];
      await Deno.writeTextFile(EXCHANGE_FILE, JSON.stringify(data, null, 4));
      ok(`Switched trader currency to ${GOLD_CURRENCY_CLASSNAME} in ${EXCHANGE_FILE}`);
    }
  } else {
    log(
      `${EXCHANGE_FILE} not generated yet - DayZ-Expansion-Market will create it (with its ` +
        `own defaults) on first server start; re-run after that to switch it to ` +
        `${GOLD_CURRENCY_CLASSNAME}`,
    );
  }

  if (await exists(MARKET_SETTINGS)) {
    const settings: MarketSettings = JSON.parse(await Deno.readTextFile(MARKET_SETTINGS));
    const currencies = Array.isArray(settings.Currencies) ? settings.Currencies as string[] : [];
    const alreadyGold = currencies.length === 1 && currencies[0] === GOLD_CURRENCY_CLASSNAME;
    if (!alreadyGold) {
      settings.Currencies = [GOLD_CURRENCY_CLASSNAME];
      await Deno.writeTextFile(MARKET_SETTINGS, JSON.stringify(settings, null, 4));
      ok(`Switched ATM currency to ${GOLD_CURRENCY_CLASSNAME} in ${MARKET_SETTINGS}`);
    }
  }
}

// How much of an item's sale price a player actually gets when selling to
// the trader (ExpansionMarketModule.c's sell path multiplies the
// stock-interpolated price by this / 100 - confirmed via unpacking
// market_scripts.pbo). Buying is completely unaffected by this setting (the
// buy path always uses a fixed 1.0 modifier) - so this is the "earning
// money should be hard" lever, paired with market.ts's BUY_PRICE_MULTIPLIER
// for the "spending money should be hard" side. DayZ-Expansion-Market's own
// default is 75 (sell for 75% of value); dropped to 20 for the 2026-08
// hardcore-survival pass - see serverpack/README.md. (A later pass briefly
// tried 12, but the project owner asked to keep this at 20 and instead
// raise rarer items' sell percentage individually - see market.ts's
// SELL_PRICE_PERCENT_OVERRIDE, which layers on top of this global value
// via DayZ-Expansion-Market's own item > zone > global fallback chain.)
const HARDCORE_SELL_PRICE_PERCENT = 20;

async function ensureHardcoreSellPricePercent(): Promise<void> {
  if (!(await exists(MARKET_SETTINGS))) return;

  const settings: MarketSettings = JSON.parse(await Deno.readTextFile(MARKET_SETTINGS));
  if (settings.SellPricePercent === HARDCORE_SELL_PRICE_PERCENT) return;

  settings.SellPricePercent = HARDCORE_SELL_PRICE_PERCENT;
  await Deno.writeTextFile(MARKET_SETTINGS, JSON.stringify(settings, null, 4));
  ok(`Set global SellPricePercent to ${HARDCORE_SELL_PRICE_PERCENT} in ${MARKET_SETTINGS}`);
}

export async function ensureCustomTrader(): Promise<void> {
  await removeDefaultZones();
  await ensureCustomTraderIdentities();
  await ensureCustomTraderGear();
  await ensureCustomZone();
  await ensureCustomTraderSafeZone();
  await ensureCustomVehicleSpawnPositions();
  await ensureGoldCoinCurrency();
  await ensureHardcoreSellPricePercent();
  await clampTraderStockToMarketCaps();
}

// Safety net for a real, confirmed data-integrity bug (2026-08 follow-up
// audit): every rebalance of src/market.ts's tier caps (TIER_MAX_STOCK) only
// ever changes the *cap* going forward - it never touches the *live* Stock
// numbers already sitting in this zone file, because those are the game's
// own persisted, real per-item quantities (see CustomZoneFile's own comment
// above - never rebuilt from scratch on purpose). Confirmed live: after this
// project tightened Common-tier stock from an old, higher default down to
// 25, 1,002 out of 2,717 managed items (37%) were still sitting at their
// old value (mostly 75) - e.g. `deersteakmeat`/`porkcan`/`tunacan` capped at
// 25 but still showing a live stock of 75. DayZ-Expansion-Market's own
// trader UI has no defined behavior for stock exceeding its own configured
// cap (that state should never arise from the mod's own normal operation -
// restocking always caps at MaxStockThreshold, only a purchase/sale ever
// changes it otherwise), and in practice this leaves those items looking
// broken/unavailable to buy in-game, while newly-added, properly-in-bounds
// items (e.g. the `Old_*` variants) display normally - exactly matching a
// report of "plenty of Old_ food, but no regular canned food or meat", even
// though the regular items were never actually removed from the trader.
// Runs after ensureCustomZone() (so the zone file/Stock map already exists)
// on every server start, clamping any classname whose live stock exceeds
// its *current* MaxStockThreshold (found by scanning only the 21 real
// merged categories, MANAGED_MARKET_CATEGORIES from market.ts - never a
// raw per-slot source file's own, unrelated stale default) down to that
// cap - a cheap, idempotent no-op once nothing is over-cap, and a
// permanent guard against this recurring after any future tier rebalance.
async function clampTraderStockToMarketCaps(): Promise<void> {
  if (!(await exists(EXPANSION_MARKET_DIR))) return;

  const zonePath = `${TRADERZONES_DIR}/${CUSTOM_ZONE_NAME}.json`;
  if (!(await exists(zonePath))) return;

  const zone: CustomZoneFile = JSON.parse(await Deno.readTextFile(zonePath));
  if (!zone.Stock || Object.keys(zone.Stock).length === 0) return;

  const caps = new Map<string, number>(); // lowercased classname -> current MaxStockThreshold
  for (const categoryName of MANAGED_MARKET_CATEGORIES) {
    const path = `${EXPANSION_MARKET_DIR}/${categoryName}.json`;
    if (!(await exists(path))) continue;
    const data: { Items?: { ClassName?: string; MaxStockThreshold?: number }[] } = JSON.parse(
      await Deno.readTextFile(path),
    );
    for (const item of data.Items ?? []) {
      if (!item.ClassName || item.MaxStockThreshold === undefined) continue;
      // Only these 21 real, merged categories are authoritative (see
      // MANAGED_MARKET_CATEGORIES comment) - deliberately NOT scanning every
      // file under EXPANSION_MARKET_DIR, since the ~50 raw per-slot source
      // files DayZ-Expansion-Market ships (e.g. Meat.json) keep their own,
      // unrelated stale default MaxStockThreshold for the same classname
      // (confirmed: Meat.json's own `deersteakmeat` entry still says 30,
      // completely unconnected to Consumables.json's real, tuned cap of 25)
      // - using those would clamp to the wrong number entirely.
      caps.set(item.ClassName.toLowerCase(), item.MaxStockThreshold);
    }
  }

  let clamped = 0;
  for (const [key, stock] of Object.entries(zone.Stock)) {
    const cap = caps.get(key);
    if (cap !== undefined && stock > cap) {
      zone.Stock[key] = cap;
      clamped++;
    }
  }

  if (clamped > 0) {
    await Deno.writeTextFile(zonePath, JSON.stringify(zone, null, 4));
    ok(`Clamped ${clamped} trader item(s) whose live stock exceeded their current cap`);
  }
}
